import React, { useState, useEffect } from 'react';
import { useSearch } from '../context/SearchContext';
import SearchBar from '../components/SearchBar';
import ProductList from '../components/ProductList';
import FilterPanel from '../components/FilterPanel';
import '../styles/Product.css';

const Product = () => {
  useEffect(() => {
    window.scrollTo({ top: 0, left: 0, behavior: 'smooth' });
  }, []);

  const { searchResults, isLoading, searchQuery } = useSearch();
  const [filteredProducts, setFilteredProducts] = useState([]);
  const [sortOption, setSortOption] = useState('bestValue');
  const [currentPage, setCurrentPage] = useState(1);
  const productsPerPage = 10;

  // Calculate total pages
  const totalPages = Math.ceil(filteredProducts.length / productsPerPage);

  // Get products for current page
  const paginatedProducts = filteredProducts.slice(
    (currentPage - 1) * productsPerPage,
    currentPage * productsPerPage
  );

  // Handle page change
  const handlePageChange = (page) => {
    if (page < 1 || page > totalPages) return;
    setCurrentPage(page);
    window.scrollTo({ top: 0, left: 0, behavior: 'smooth' });
  };

  // Reset to first page when filters or results change
  useEffect(() => {
    setCurrentPage(1);
  }, [filteredProducts]);

  // Apply filters to the search results
  const handleFilterChange = (filters) => {
    if (!searchResults) return;

    const filtered = searchResults.filter(product => {
      // Apply price filter
      const price = parseFloat(product.price) || 0;
      if (price < filters.priceRange[0] || price > filters.priceRange[1]) {
        return false;
      }
      // Apply platform filter
      if (filters.platforms && filters.platforms.length === 0) {
        return false; // No platforms selected, show nothing
      }
      if (filters.platforms && filters.platforms.length > 0 && !filters.platforms.includes(product.platform)) {
        return false;
      }
      // Apply rating filter (now min and max)
      const rating = parseFloat(product.rating) || 0;
      if (typeof filters.ratingMin === 'number' && rating < filters.ratingMin) {
        return false;
      }
      if (typeof filters.ratingMax === 'number' && rating > filters.ratingMax) {
        return false;
      }
      return true;
    });

    // Apply sorting
    const sorted = sortProducts(filtered, sortOption);
    setFilteredProducts(sorted);
  };

  // Sort products based on selected option
  const sortProducts = (products, option) => {
    const sortedProducts = [...products];

    switch (option) {
      case 'priceLow':
        sortedProducts.sort((a, b) => (parseFloat(a.price) || 0) - (parseFloat(b.price) || 0));
        break;
      case 'priceHigh':
        sortedProducts.sort((a, b) => (parseFloat(b.price) || 0) - (parseFloat(a.price) || 0));
        break;
      case 'rating':
        sortedProducts.sort((a, b) => (parseFloat(b.rating) || 0) - (parseFloat(a.rating) || 0));
        break;
      case 'mb':
        sortedProducts.sort((a, b) => (parseFloat(b.mb_score) || 0) - (parseFloat(a.mb_score) || 0));
        break;
      case 'cb':
        sortedProducts.sort((a, b) => (parseFloat(b.cb_score) || 0) - (parseFloat(a.cb_score) || 0));
        break;
      case 'bestValue':
      default:
        sortedProducts.sort((a, b) => {
          const scoreA = (parseFloat(a.mb_score) || 0) + (parseFloat(a.cb_score) || 0);
          const scoreB = (parseFloat(b.mb_score) || 0) + (parseFloat(b.cb_score) || 0);
          return scoreB - scoreA;
        });
        break;
    }

    return sortedProducts;
  };

  // Handle sort change
  const handleSortChange = (e) => {
    const option = e.target.value;
    setSortOption(option);
    setFilteredProducts(prevProducts => sortProducts(prevProducts, option));
  };

  // Update filtered products when search results change
  useEffect(() => {
    if (searchResults) {
      const sorted = sortProducts(searchResults, sortOption);
      setFilteredProducts(sorted);
    }
  }, [searchResults, sortOption]);

  // On initial mount, show persisted search results if available
  useEffect(() => {
    if (searchResults && searchResults.length > 0) {
      setFilteredProducts(sortProducts(searchResults, sortOption));
    }
  }, []);

  return (
    <div className="product-page">
      <div className="product-header">
        <div className="container">
          <h1>Products</h1>
          <div className="search-container">
            <SearchBar />
          </div>
        </div>
      </div>

      <div className="container">
        <div className="row">
          {/* Filter Panel on the left */}
          <div className="col-lg-3 filter-column">
            <FilterPanel products={searchResults || []} onFilterChange={handleFilterChange} />
          </div>

          {/* Product Results on the right */}
          <div className="col-lg-9 product-results-column">
            {searchQuery && (
              <div className="search-info">
                <h2>
                  Results for: <span className="search-query">"{searchQuery}"</span>
                </h2>
                <p className="result-count">
                  {filteredProducts.length} {filteredProducts.length === 1 ? 'product' : 'products'} found
                </p>
              </div>
            )}
            {isLoading ? (
              <div className="loading-container">
                <div className="spinner-border text-primary" role="status">
                  <span className="visually-hidden">Loading...</span>
                </div>
                <p>Searching across multiple stores...</p>
              </div>
            ) : (
              <>
                {filteredProducts && filteredProducts.length > 0 ? (
                  <div className="product-controls">
                    <div className="sort-controls">
                      <label htmlFor="sort-select">Sort by:</label>
                      <select 
                        id="sort-select" 
                        className="form-select"
                        value={sortOption}
                        onChange={handleSortChange}
                      >
                        <option value="bestValue">Best Value</option>
                        <option value="priceLow">Price: Low to High</option>
                        <option value="priceHigh">Price: High to Low</option>
                        <option value="rating">Rating</option>
                        <option value="mb">MB Score</option>
                        <option value="cb">CB Score</option>
                      </select>
                    </div>
                  </div>
                ) : searchQuery ? (
                  <div className="no-results">
                    <i className="fas fa-search"></i>
                    <h3>No products found</h3>
                    <p>Try a different search term or adjust your filters.</p>
                  </div>
                ) : (
                  <div className="start-search">
                    <i className="fas fa-search"></i>
                    <h3>Search for products to get started</h3>
                    <p>Enter a product name, brand, or category in the search bar above.</p>
                  </div>
                )}
                {filteredProducts && filteredProducts.length > 0 && (
                  <>
                    <ProductList products={paginatedProducts} />
                    {/* Pagination Controls */}
                    <nav className="pagination-nav mt-4">
                      <ul className="pagination justify-content-center">
                        <li className={`page-item${currentPage === 1 ? ' disabled' : ''}`}>
                          <button className="page-link" onClick={() => handlePageChange(currentPage - 1)} disabled={currentPage === 1}>&laquo; Prev</button>
                        </li>
                        {Array.from({ length: totalPages }, (_, i) => (
                          <li key={i + 1} className={`page-item${currentPage === i + 1 ? ' active' : ''}`}>
                            <button className="page-link" onClick={() => handlePageChange(i + 1)}>{i + 1}</button>
                          </li>
                        ))}
                        <li className={`page-item${currentPage === totalPages ? ' disabled' : ''}`}>
                          <button className="page-link" onClick={() => handlePageChange(currentPage + 1)} disabled={currentPage === totalPages}>Next &raquo;</button>
                        </li>
                      </ul>
                    </nav>
                  </>
                )}
              </>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Product;
